import { ReactNode, FC } from 'react';

interface ModalProps {
    /** 是否显示 (受控模式) */
    open?: boolean;
    /** 默认是否显示 (非受控模式) */
    defaultOpen?: boolean;
    /** 显示状态变化回调 */
    onOpenChange?: (open: boolean) => void;
    /** 标题 */
    title?: ReactNode;
    /** 关闭回调 (onOpenChange 的简化版，仅在关闭时触发) */
    onClose?: () => void;
    /** 确认回调 */
    onConfirm?: () => void;
    /** 确认按钮文字 */
    confirmText?: string;
    /** 取消按钮文字 */
    cancelText?: string;
    /** 是否显示关闭按钮 */
    closable?: boolean;
    /** 点击遮罩是否关闭 */
    closeOnOverlayClick?: boolean;
    /** 是否显示底部按钮 */
    showFooter?: boolean;
    /** 自定义底部 */
    footer?: ReactNode;
    /** 子元素 */
    children?: ReactNode;
    /** 自定义类名 */
    className?: string;
}
interface ModalContentProps {
    children?: ReactNode;
    className?: string;
}
interface ModalHeaderProps {
    children?: ReactNode;
    closable?: boolean;
    onClose?: () => void;
}
interface ModalBodyProps {
    children?: ReactNode;
    className?: string;
}
interface ModalFooterProps {
    children?: ReactNode;
    className?: string;
}

declare const ModalContent: FC<ModalContentProps>;
declare const ModalHeader: FC<ModalHeaderProps>;
declare const ModalBody: FC<ModalBodyProps>;
declare const ModalFooter: FC<ModalFooterProps>;
declare const Modal: FC<ModalProps> & {
    Content: typeof ModalContent;
    Header: typeof ModalHeader;
    Body: typeof ModalBody;
    Footer: typeof ModalFooter;
};

export { Modal, Modal as default };
export type { ModalBodyProps, ModalContentProps, ModalFooterProps, ModalHeaderProps, ModalProps };
